        void loadHome(){section="home";renderShell();loading();int token=++generation;OscarApi.get("api/v2/home.php",OscarApi.params("app_version",114),(v,e)->{if(token!=generation)return;if(e!=null){error(e,this::loadHome);return;}clear();ArrayList<Item> all=collect(v,null,220);if(all.isEmpty()){error("لم يصل محتوى من Oscar TV.",this::loadHome);return;}ArrayList<Item> series=filter(all,"series"),movies=filter(all,"movie"),anime=filter(all,"anime"),channels=filter(all,"channel"),episodes=filter(all,"episode");Item hero=!series.isEmpty()?series.get(0):all.get(0);hero(hero);if(!episodes.isEmpty())rail("أحدث الحلقات",episodes);if(!series.isEmpty())rail("مسلسلات Oscar TV",series);if(!movies.isEmpty())rail("أفلام Oscar TV",movies);if(!anime.isEmpty())rail("الأنمي",anime);if(!channels.isEmpty())rail("القنوات",channels);});}
        void loadList(String kind,String q){section=kind;renderShell();loading();String path;Map<String,String> p;if(kind.equals("movie")){path="api/movies/";p=OscarApi.params("page",1,"limit",60,"app_version",114);}else if(kind.equals("anime")){path="api/anime/";p=OscarApi.params("page",1,"limit",60,"search",q);}else if(kind.equals("channel")){path="api/channels/";p=OscarApi.params("page",1,"limit",60,"search",q);}else{path="api/series/";p=OscarApi.params("page",1,"limit",60,"search",q,"app_version",114);}if(q!=null&&!q.isEmpty())p.put("search",q);int token=++generation;OscarApi.get(path,p,(v,e)->{if(token!=generation)return;if(e!=null){error(e,()->loadList(kind,q));return;}clear();ArrayList<Item> list=collect(v,kind,180);if(list.isEmpty()){TextView m=Ui.text(a,"لا توجد نتائج",16,false);m.setGravity(Gravity.CENTER);m.setTextColor(Ui.muted(a));m.setPadding(0,Ui.dp(a,45),0,0);content.addView(m);return;}grid(list);});}
