        void searchAll(String q){if(q.isEmpty())return;section="search";renderShell();loading();ArrayList<Item> merged=new ArrayList<>();AtomicInteger left=new AtomicInteger(4);int token=++generation;String[] kinds={"series","movie","anime","channel"};for(String k:kinds){String path=k.equals("movie")?"api/movies/":k.equals("anime")?"api/anime/":k.equals("channel")?"api/channels/":"api/series/";Map<String,String> p=OscarApi.params("page",1,"limit",35,"search",q,"app_version",114);OscarApi.get(path,p,(v,e)->{if(token!=generation)return;if(e==null)merged.addAll(collect(v,k,80));if(left.decrementAndGet()==0){clear();if(merged.isEmpty()){TextView m=Ui.text(a,"لا توجد نتائج للبحث",16,false);m.setGravity(Gravity.CENTER);content.addView(m);}else grid(unique(merged));}});}}
        void hero(Item i){FrameLayout f=new FrameLayout(a);ImageView img=Ui.image(a,OscarApi.absolute(i.banner.isEmpty()?i.poster:i.banner),18);f.addView(img,new FrameLayout.LayoutParams(-1,-1));LinearLayout sh=Ui.column(a);sh.setGravity(Gravity.BOTTOM);sh.setPadding(Ui.dp(a,16),0,Ui.dp(a,16),Ui.dp(a,15));sh.setBackgroundColor(0x55000000);TextView brand=Ui.text(a,"OSCAR TV",12,true);brand.setTextColor(Ui.ACCENT);sh.addView(brand);TextView name=Ui.text(a,i.title,24,true);name.setMaxLines(2);sh.addView(name);if(!i.sub.isEmpty()){TextView su=Ui.text(a,i.sub,13,false);su.setTextColor(0xffdddddd);sh.addView(su);}f.addView(sh,new FrameLayout.LayoutParams(-1,-1));f.setOnClickListener(v->detail(i));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,Ui.dp(a,225));lp.topMargin=Ui.dp(a,10);content.addView(f,lp);}
