        void detail(Item i){backs.addLast(()->{backs.clear();if(section.equals("home"))loadHome();else if(section.equals("search"))searchAll("");else loadList(section,null);});loading();String path=i.kind.equals("movie")?"api/movies/show.php":i.kind.equals("anime")?"api/anime/show.php":i.kind.equals("channel")?"api/channels/show.php":i.kind.equals("episode")?"api/episodes/show.php":"api/series/show.php";int token=++generation;OscarApi.get(path,OscarApi.params("id",i.id),(v,e)->{if(token!=generation)return;if(e!=null){error(e,()->detail(i));return;}JSONObject d=findObject(v);if(d==null)d=i.raw;drawDetail(i,d);});}
