    static int intv(JSONObject o,String...ks){for(String k:ks){Object v=o.opt(k);if(v instanceof Number)return ((Number)v).intValue();try{if(v instanceof String)return Integer.parseInt((String)v);}catch(Exception ignored){}}return 0;}
    static String pick(JSONObject o,String...ks){for(String k:ks){String v=o.optString(k,"").trim();if(!v.isEmpty()&&!"null".equals(v))return v;}return "";}
    static String pick(JSONObject o,String k1,String k2,String k3,String fallback1,String fallback2){String x=pick(o,k1,k2,k3);return x.isEmpty()?(!fallback1.isEmpty()?fallback1:fallback2):x;}
